CREATE VIEW교수별수강학생(교수번호, 학번, 과목번호, 성적)
ASSELECT교수.교수번호, 학번, 과목번호, 성적
FROM교수, 수강
WHERE교수.교수번호= 수강.교수번호;
INSERTINTO 교수별수강학생(학번, 과목번호, 성적)
VALUES(‘300’,‘C002’, ‘B’);

CREATEVIEW교수명단
